//! Shared UI chrome: the generated skin, nav, theme settings, and small helpers.

use topcoat::{
    Result,
    context::Cx,
    view::{Unescaped, View, component, view},
};

use crate::skin::{FONTS, PALETTES, SCHEMES, STYLES};

/// The whole look, generated by scripts/gen-skin.py from design/useby.
/// Re-exported so pages keep importing it from here.
pub(crate) use crate::skin::CSS;

/// Cookie that remembers the owner's theme choices across visits:
/// "pal:scheme:font:style". Cookies written before the style axis carry only
/// three fields; the missing one falls back to the default.
pub(crate) const SKIN_COOKIE: &str = "lotel_skin";

/// The four switches the settings panel offers. Values are what ride the
/// data-pal / data-scheme / data-font / data-style attributes; the generated
/// CSS maps every combination through token blocks, so the server only ever
/// picks four strings from these tables — no free-form colors cross the seam.
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct Skin {
    pub(crate) pal: &'static str,
    pub(crate) scheme: &'static str,
    pub(crate) font: &'static str,
    pub(crate) style: &'static str,
}

/// What a first-time visitor sees: the lime day suit in the house type and
/// the chunky style.
pub(crate) const DEFAULT_SKIN: Skin = Skin {
    pal: "lime",
    scheme: "day",
    font: "recursive",
    style: "chunky",
};

/// Resolve the panel's four values: query parameters beat the cookie, the
/// cookie beats the defaults, and anything unrecognized falls through to the
/// next source rather than trusting input.
pub(crate) fn parse_skin(cookie: Option<&str>, query: &str) -> Skin {
    let mut qpal = None;
    let mut qsch = None;
    let mut qfont = None;
    let mut qstyle = None;
    for kv in query.split('&').filter(|s| !s.is_empty()) {
        let Some((k, v)) = kv.split_once('=') else {
            continue;
        };
        match k {
            "pal" => qpal = Some(v),
            "scheme" => qsch = Some(v),
            "font" => qfont = Some(v),
            "style" => qstyle = Some(v),
            _ => {}
        }
    }
    // "pal:scheme:font:style"; a legacy three-field cookie simply yields
    // None for the fourth, which resolves to the default below.
    let (cpal, csch, cfont, cstyle) = match cookie {
        Some(c) => {
            let mut it = c.split(':');
            (it.next(), it.next(), it.next(), it.next())
        }
        None => (None, None, None, None),
    };
    Skin {
        pal: resolve_with(qpal, cpal, PALETTES, DEFAULT_SKIN.pal),
        scheme: resolve_with(qsch, csch, SCHEMES, DEFAULT_SKIN.scheme),
        font: resolve_with(qfont, cfont, FONTS, DEFAULT_SKIN.font),
        style: resolve_with(qstyle, cstyle, STYLES, DEFAULT_SKIN.style),
    }
}

fn resolve_with(
    q: Option<&str>,
    c: Option<&str>,
    table: &[(&'static str, &'static str)],
    dflt: &'static str,
) -> &'static str {
    [q, c]
        .into_iter()
        .flatten()
        .find_map(|w| table.iter().find(|(v, _)| *v == w).map(|(v, _)| *v))
        .unwrap_or(dflt)
}

/// True when the query carries any skin switch — the signal to (re)write the
/// cookie so the choice survives the next navigation.
pub(crate) fn query_has_skin(query: &str) -> bool {
    query.split('&').any(|kv| {
        matches!(
            kv.split('=').next().unwrap_or(""),
            "pal" | "scheme" | "font" | "style"
        )
    })
}

/// One retention sticker in the top bar: the signal's short name and its
/// already-shortened ttl ("logs", "7d"). Owned so the boxed view can move it in.
pub(crate) struct UseBy {
    pub(crate) signal: &'static str,
    pub(crate) ttl: String,
}

/// Shorten a human ttl for the use-by sticker: "7 days" -> "7d", "12 hours"
/// -> "12h", "30 minutes" -> "30m", "1 day" -> "1d". Anything it does not
/// recognise ("7 weeks", "", junk) is returned unchanged — the sticker shows
/// the raw policy text rather than inventing one.
pub(crate) fn short_ttl(ttl: &str) -> String {
    let Some((n, unit)) = ttl.trim().split_once(' ') else {
        return ttl.to_string();
    };
    let letter = match unit.trim() {
        "day" | "days" => "d",
        "hour" | "hours" => "h",
        "minute" | "minutes" => "m",
        _ => return ttl.to_string(),
    };
    if n.is_empty() || !n.bytes().all(|b| b.is_ascii_digit()) {
        return ttl.to_string();
    }
    format!("{n}{letter}")
}

/// Thousands-separate a decimal integer for the big numbers on stat tiles
/// and facet counts ("445806" -> "445,806"). Anything that is not a plain
/// integer (query-failure placeholders, decimals) passes through untouched.
/// Table cells and the Explore grid never run through this.
pub(crate) fn thousands(s: &str) -> String {
    let (sign, digits) = match s.strip_prefix('-') {
        Some(rest) => ("-", rest),
        None => ("", s),
    };
    if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return s.to_string();
    }
    let mut out = String::with_capacity(digits.len() + digits.len() / 3 + 1);
    out.push_str(sign);
    let bytes = digits.as_bytes();
    for (i, b) in bytes.iter().enumerate() {
        if i > 0 && (bytes.len() - i) % 3 == 0 {
            out.push(',');
        }
        out.push(*b as char);
    }
    out
}

/// Settings-panel href: keep the page's own query (filters and friends),
/// drop any stale skin params, append this choice. Option values come from
/// the fixed tables above, so no encoding is needed.
pub(crate) fn panel_href(query: &str, key: &str, val: &str) -> String {
    let mut out = String::from("?");
    for kv in query.split('&').filter(|s| !s.is_empty()) {
        let k = kv.split('=').next().unwrap_or("");
        if matches!(k, "pal" | "scheme" | "font" | "style") || k == key {
            continue;
        }
        if out.len() > 1 {
            out.push('&');
        }
        out.push_str(kv);
    }
    if out.len() > 1 {
        out.push('&');
    }
    out.push_str(key);
    out.push('=');
    out.push_str(val);
    out
}

/// "lime · day · recursive · chunky" — the summary's live readout,
/// server-rendered. Takes bare strs so callers holding owned copies (the
/// panel) need not construct a whole Skin.
pub(crate) fn skin_readout(pal: &str, scheme: &str, font: &str, style: &str) -> String {
    let scheme = SCHEMES
        .iter()
        .find(|(v, _)| *v == scheme)
        .map(|(_, l)| *l)
        .unwrap_or(scheme);
    format!("{pal} · {scheme} · {font} · {style}")
}

/// The theme settings panel: a sticky bar over the content column whose
/// `details/summary` popover holds the palette, colourway, type, and style
/// choices, mirroring the mock's `details.set` in design/useby.
/// Server-side only — each option is a GET link that re-renders the page with
/// a new skin (and the layout writes the cookie), so no script is needed to
/// operate it. The panel starts open when the query carries a skin switch, so
/// a deep link shows what it changed; otherwise it rests collapsed.
#[component]
pub(crate) async fn theme_panel(
    cx: &Cx,
    pal: String,
    scheme: String,
    font: String,
    style: String,
    query: String,
    usebys: Vec<UseBy>,
) -> Result<impl View> {
    let open = query_has_skin(&query);
    let readout = skin_readout(&pal, &scheme, &font, &style);
    Ok(view! {
        <header class="top">
            <div class="useby-strip" role="group" aria-label="Retention">
                <span class="useby-cap">"forgets after"</span>
                for u in usebys {
                    <span class="useby"><span class="useby-k">(u.signal)</span>" "<b>(u.ttl)</b></span>
                }
            </div>
            <details class="set" if open { open="" }>
                <summary title=(readout.clone())>
                    <span class="pv" aria-hidden="true">
                        <i class="p"></i><i class="a"></i><i class="c"></i>
                    </span>
                    <span class="who">"look"</span>
                </summary>
                <div class="pop">
                    <div class="grp" role="group" aria-label="Palette">
                        <span class="gk">"Palette"</span>
                        for (v, label) in PALETTES {
                            <a class=(if *v == pal { "box on" } else { "box" })
                               data-k="pal"
                               data-v=(v.to_string())
                               data-p=(v.to_string())
                               href=(panel_href(&query, "pal", v))>
                                <i class="sw a" aria-hidden="true"></i>
                                <i class="sw b" aria-hidden="true"></i>
                                <i class="sw c" aria-hidden="true"></i>
                                <i class="sw d" aria-hidden="true"></i>
                                (label.to_string())
                            </a>
                        }
                    </div>
                    <div class="grp" role="group" aria-label="Colourway">
                        <span class="gk">"Colourway"</span>
                        for (v, label) in SCHEMES {
                            <a class=(if *v == scheme { "box on" } else { "box" })
                               data-k="scheme"
                               data-v=(v.to_string())
                               data-p=""
                               href=(panel_href(&query, "scheme", v))>
                                (label.to_string())
                            </a>
                        }
                    </div>
                    <div class="grp" role="group" aria-label="Type">
                        <span class="gk">"Type"</span>
                        for (v, label) in FONTS {
                            <a class=(if *v == font { "box on" } else { "box" })
                               data-k="font"
                               data-v=(v.to_string())
                               data-p=""
                               href=(panel_href(&query, "font", v))>
                                (label.to_string())
                            </a>
                        }
                    </div>
                    <div class="grp" role="group" aria-label="Style">
                        <span class="gk">"Style"</span>
                        for (v, label) in STYLES {
                            <a class=(if *v == style { "box on" } else { "box" })
                               data-k="style"
                               data-v=(v.to_string())
                               data-p=""
                               href=(panel_href(&query, "style", v))>
                                (label.to_string())
                            </a>
                        }
                    </div>
                    <p class="law">
                        "The accent is what you do. The second hue is what the probe measured. Red is the fault. The sticker is when it forgets."
                    </p>
                </div>
            </details>
        </header>
    })
}

/// One cell of a DB row, rendered safely even when the row is a query-failure
/// placeholder: those carry a single wide cell, not `arity` of them, and
/// indexing past the end took pages down at 500 (the M17 stress finding).
pub(crate) fn cell(row: &[String], i: usize) -> String {
    row.get(i).cloned().unwrap_or_default()
}

/// The sticker the agent pages show while content display is opted in (§5):
/// `content: shown` by the page title, so a lotel that displays prompt text
/// can never be read as the private default. While the redactor is on — the
/// default — it renders nothing: there is nothing to admit.
///
/// The agent pages (T3–T7) interpolate it next to their titles; until they
/// land it has no caller, hence the allow.
#[allow(dead_code)]
pub(crate) fn content_marker(cx: &Cx, shown: bool) -> impl View {
    view! {
        if shown {
            <span class="badge warn" title="LOTEL_AGENT_SHOW_CONTENT is set: prompt and tool content are displayed">
                "content: shown"
            </span>
        }
    }
}

/// Sidebar nav: (label, path).
pub(crate) fn nav_links() -> [(&'static str, &'static str); 7] {
    [
        ("Dashboard", "/"),
        ("Logs", "/logs"),
        ("Traces", "/traces"),
        ("Metrics", "/metrics"),
        ("Explore", "/query"),
        ("Services", "/services"),
        ("Storage", "/storage"),
    ]
}

/// Lowercase severity family for badge styling.
pub(crate) fn sev_class(sev: &str) -> &'static str {
    match sev.to_ascii_uppercase().as_str() {
        "TRACE" | "TRACE2" | "TRACE3" | "TRACE4" => "trace",
        "DEBUG" | "DEBUG2" | "DEBUG3" | "DEBUG4" => "debug",
        "INFO" | "INFORMATION" | "INFORMATIONAL" | "NOTICE" => "info",
        "WARN" | "WARNING" => "warn",
        "ERROR" | "ERR" | "FATAL" | "CRITICAL" | "CRIT" | "EMERGENCY" | "EMERG" | "ALERT" => {
            if sev.eq_ignore_ascii_case("FATAL") || sev.eq_ignore_ascii_case("CRITICAL") {
                "fatal"
            } else {
                "error"
            }
        }
        _ => "other",
    }
}

#[cfg(test)]
mod tests {
    use super::{
        DEFAULT_SKIN, Skin, content_marker, panel_href, parse_skin, query_has_skin, sev_class,
        short_ttl, skin_readout, thousands,
    };
    use topcoat::{context::Cx, view::ViewExt};

    /// The opt-in marker (§5): it says `content: shown` when content is being
    /// displayed and stays out of the page otherwise.
    #[tokio::test]
    async fn content_marker_only_appears_when_content_is_shown() {
        let cx = Cx::new();
        let on = content_marker(&cx, true).single().await.unwrap().render(&cx);
        assert!(on.contains("content: shown"), "{on}");
        assert!(on.contains("badge warn"), "a house badge, no new CSS: {on}");

        let off = content_marker(&cx, false).single().await.unwrap().render(&cx);
        assert!(!off.contains("content"), "masked is silent: {off}");
    }

    #[test]
    fn short_ttl_shortens_the_recognised_units() {
        assert_eq!(short_ttl("7 days"), "7d");
        assert_eq!(short_ttl("12 hours"), "12h");
        assert_eq!(short_ttl("30 minutes"), "30m");
        assert_eq!(short_ttl("1 day"), "1d");
        assert_eq!(short_ttl("30 days"), "30d");
        // Surrounding blanks never reach the sticker.
        assert_eq!(short_ttl("  3 days "), "3d");
    }

    #[test]
    fn short_ttl_passes_unrecognised_input_through_unchanged() {
        assert_eq!(short_ttl("7d"), "7d");
        assert_eq!(short_ttl("7 weeks"), "7 weeks");
        assert_eq!(short_ttl("banana days"), "banana days");
        assert_eq!(short_ttl("7 days flat"), "7 days flat");
        assert_eq!(short_ttl(""), "");
        assert_eq!(short_ttl("1days"), "1days");
    }

    #[test]
    fn thousands_groups_digits_in_threes() {
        assert_eq!(thousands("445806"), "445,806");
        assert_eq!(thousands("0"), "0");
        assert_eq!(thousands("999"), "999");
        assert_eq!(thousands("1000"), "1,000");
        assert_eq!(thousands("1234567"), "1,234,567");
        assert_eq!(thousands("1000000000"), "1,000,000,000");
        assert_eq!(thousands("-445806"), "-445,806");
    }

    #[test]
    fn thousands_leaves_non_integers_alone() {
        // Error placeholders and decimals must render exactly as the query gave them.
        assert_eq!(thousands(""), "");
        assert_eq!(thousands("445.0"), "445.0");
        assert_eq!(thousands("error: no such table"), "error: no such table");
        assert_eq!(thousands("1,000"), "1,000");
    }

    #[test]
    fn severity_families() {
        assert_eq!(sev_class("INFO"), "info");
        assert_eq!(sev_class("information"), "info");
        assert_eq!(sev_class("WARN"), "warn");
        assert_eq!(sev_class("WARNING"), "warn");
        assert_eq!(sev_class("ERROR"), "error");
        assert_eq!(sev_class("FATAL"), "fatal");
        assert_eq!(sev_class("critical"), "fatal");
        assert_eq!(sev_class(""), "other");
        assert_eq!(sev_class("banana"), "other");
    }

    #[test]
    fn skin_defaults_when_nothing_is_offered() {
        assert_eq!(parse_skin(None, ""), DEFAULT_SKIN);
    }

    #[test]
    fn skin_cookie_beats_defaults_query_beats_cookie() {
        let from_cookie = parse_skin(Some("riso:day:onest:crisp"), "");
        assert_eq!(
            from_cookie,
            Skin {
                pal: "riso",
                scheme: "day",
                font: "onest",
                style: "crisp"
            }
        );

        let override_ = parse_skin(Some("riso:day:onest:crisp"), "pal=sherbet&scheme=night&style=chunky");
        assert_eq!(override_.pal, "sherbet");
        assert_eq!(override_.scheme, "night");
        assert_eq!(override_.font, "onest"); // untouched by the query: the cookie stands
        assert_eq!(override_.style, "chunky");
    }

    #[test]
    fn skin_style_defaults_and_legacy_three_field_cookie_still_parses() {
        // Nothing offered: the house style is chunky.
        assert_eq!(parse_skin(None, "").style, "chunky");
        // A cookie written before the style axis carries only three fields:
        // they still parse, and the missing style falls back to the default.
        let legacy = parse_skin(Some("riso:night:figtree"), "");
        assert_eq!(legacy.pal, "riso");
        assert_eq!(legacy.scheme, "night");
        assert_eq!(legacy.font, "figtree");
        assert_eq!(legacy.style, DEFAULT_SKIN.style);
    }

    #[test]
    fn skin_style_query_beats_cookie_beats_default() {
        let from_cookie = parse_skin(Some("riso:night:figtree:crisp"), "");
        assert_eq!(from_cookie.style, "crisp"); // the cookie's word stands
        let override_ = parse_skin(Some("riso:night:figtree:crisp"), "style=chunky");
        assert_eq!(override_.style, "chunky"); // the query outranks it
    }

    #[test]
    fn skin_style_junk_values_are_ignored() {
        // Garbage on the new axis never reaches the HTML either.
        let junk = parse_skin(Some("riso:day:figtree:smooth"), "style=<script>");
        assert_eq!(junk.style, DEFAULT_SKIN.style);
    }

    #[test]
    fn skin_style_panel_link_preserves_page_filters() {
        assert_eq!(
            panel_href("service=api&style=crisp&from=1h", "style", "chunky"),
            "?service=api&from=1h&style=chunky"
        );
        assert!(query_has_skin("style=chunky"));
    }

    #[test]
    fn skin_ignores_unrecognized_values_from_any_source() {
        // Garbage must fall through the whole chain, never reach the HTML.
        let junk = parse_skin(Some("evil:night:hack:smooth"), "pal=<script>&font=nope&style=<b>");
        assert_eq!(junk.pal, DEFAULT_SKIN.pal);
        assert_eq!(junk.font, DEFAULT_SKIN.font);
        assert_eq!(junk.style, DEFAULT_SKIN.style);
        assert_eq!(junk.scheme, "night"); // valid in the cookie, kept
        // Partial cookies behave the same: missing segments use the default.
        let short = parse_skin(Some("mint"), "");
        assert_eq!(short.pal, "mint");
        assert_eq!(short.scheme, DEFAULT_SKIN.scheme);
    }

    #[test]
    fn skin_query_presence_drives_cookie_writes() {
        assert!(query_has_skin("pal=mint"));
        assert!(query_has_skin("service=api&font=figtree&x=1"));
        assert!(!query_has_skin("service=api&from=1h"));
        assert!(!query_has_skin(""));
    }

    #[test]
    fn panel_links_preserve_page_filters_and_replace_stale_choices() {
        // The page's own filters ride along; old skin params get dropped.
        assert_eq!(
            panel_href("service=api&pal=riso&from=1h", "scheme", "night"),
            "?service=api&from=1h&scheme=night"
        );
        // Choosing the same key twice keeps only the newest value.
        assert_eq!(panel_href("font=figtree", "font", "onest"), "?font=onest");
        // Empty query collapses to the bare parameter.
        assert_eq!(panel_href("", "pal", "mint"), "?pal=mint");
    }

    #[test]
    fn readout_names_the_scheme_as_the_panel_shows_it() {
        assert_eq!(
            skin_readout("riso", "system", "figtree", "chunky"),
            "riso · auto · figtree · chunky"
        );
        // An unrecognized scheme would be impossible through the panel, but
        // the readout must still echo something rather than vanish.
        assert_eq!(skin_readout("mint", "dusk", "onest", "crisp"), "mint · dusk · onest · crisp");
    }
}

/// The live-refresh controller, embedded once per page that opts in. Polls a
/// `/api/live?topic=` fragment and swaps the target's HTML — pausing when the
/// tab is hidden and when the toggle is off. This is the single client half of
/// the freshness seam: swap its `fetch` for an `EventSource` to go push-based
/// (the SaaS shape) without touching any page.
///
/// The swap keeps the reader's place: rows whose `<details>` stands open are
/// remembered by their `data-key` (the server stamps every expandable row a
/// key derived from its own data — time, span id, body hash — so the same row
/// keeps the same key across refreshes) and re-opened after the swap; and the
/// swap is skipped outright while text inside the target is selected, so a
/// copy is never yanked away.
pub(crate) const LIVE_JS: &str = r#"
window.LotelLive=(function(){
  function sub(o){
    var t=document.getElementById(o.target);
    if(!t) return;
    var ctl=o.toggle?document.getElementById(o.toggle):null;
    var base='/api/live?topic='+encodeURIComponent(o.topic);
    var ms=o.cadence||5000, timer=null;
    function url(){ var s=window.location.search||''; return base+(s?'&'+s.replace(/^\?/,''):''); }
    function selectedInTarget(){
      var s=document.getSelection?document.getSelection():null;
      if(!s||s.isCollapsed||!s.rangeCount) return false;
      for(var n=s.anchorNode;n;n=n.parentNode) if(n===t) return true;
      for(n=s.focusNode;n;n=n.parentNode) if(n===t) return true;
      return false;
    }
    function openKeys(){
      var m={}, ds=t.querySelectorAll('details[data-key]');
      for(var i=0;i<ds.length;i++) if(ds[i].open) m[ds[i].getAttribute('data-key')]=1;
      return m;
    }
    function restoreKeys(m){
      var ds=t.querySelectorAll('details[data-key]');
      for(var i=0;i<ds.length;i++) if(m[ds[i].getAttribute('data-key')]) ds[i].open=true;
    }
    function tick(){
      if(document.hidden) return;
      fetch(url(),{cache:'no-store'}).then(function(r){return r.text();}).then(function(h){
        if(selectedInTarget()) return;
        var m=openKeys();
        t.innerHTML=h;
        restoreKeys(m);
      }).catch(function(){});
    }
    function on(){ if(!timer){ t.setAttribute('data-live','on'); timer=setInterval(tick,ms); tick(); } }
    function off(){ if(timer){ clearInterval(timer); timer=null; } t.setAttribute('data-live','off'); }
    function sync(){ if(ctl && !ctl.checked) off(); else on(); }
    if(ctl) ctl.addEventListener('change',sync);
    sync();
  }
  return {sub:sub};
})();
"#;

/// Opt a region into live refresh: loads the controller and subscribes `target`
/// to `/api/live?topic=` while `toggle` is checked. Pauses when hidden.
#[component]
pub(crate) async fn live_refresh(
    cx: &Cx,
    topic: String,
    target: String,
    toggle: String,
    cadence: u32,
) -> Result<impl View> {
    let boot = format!(
        "LotelLive.sub({{topic:{topic:?},target:{target:?},toggle:{toggle:?},cadence:{cadence}}});"
    );
    Ok(view! {
        <script>(Unescaped::new_unchecked(LIVE_JS))</script>
        <script>(Unescaped::new_unchecked(boot))</script>
    })
}
